/* full: 闂備礁鎲￠〃鍡椕洪弽顓熷仱鐟滃繒鍒掗銏℃櫇闁逞屽墴瀹曟洖顫濇潏顭戞綗闂佺粯锚濡﹪宕澶嬬厪闁糕剝娲滅花绺嶤II 濠电偞鍨堕幐鎼佹煀閿濆拋鐒?ASCII 缂傚倸鍊烽懗鍫曞窗瀹ュ洨鍗氶悗闈涙啞鐏?TTF_GetGlyphMetrics(闂?
 * fallback chain,CJK/emoji 闂佽娴烽、濠偽涢崟顓涘亾閻熸澘鏆辨い顐犲灲閺佹劙宕堕敐鍌氫壕?,濠?glyph_img_ttf 闂?advance 闂備礁鎲￠懝楣冨嫉椤掑倽濮?
 * 婵犵數鍋為幐绋款嚕閸洘鍋傞悗锝庡亝婵鈧箍鍎卞ú銊╁几閸屾埃妲堥柟鐐▕椤庢绱掗弮鍫濞寸媴绠撻崺鈧い鎺戝€甸崑鎾舵兜閸涱噮妫勯柣搴ｎ攰濞呮洜绮欐径鎰ㄩ柨鏃€鍎抽ˉ鏇熺箾閹寸偞灏ㄩ柛瀣崌閺屻倝鏌ㄧ€ｎ剚娈梺閫炲苯鍘哥紒顔捐懀CII 闂備焦妞垮鍧楀礉鎼达絾顫曢柨鏃堟暜閸嬫挸鈽夊▎妯煎姼闂?闂?ASCII 闂?(font,cp) 缂傚倸鍊搁崐褰掑箰閹间焦鍋ら柕濞炬櫅杩?*/
static int glyph_ttf(unsigned int cp, void* st)
{
    TextMeasureCtx* c = static_cast<TextMeasureCtx*>(st);
    TTF_Font* font = render_get_font(c->r, c->family, c->fs,
                                     c->bold ? kFontBold : 0);
    if (!font) {
        return 0;
    }
    if (cp < 0x80) {
        if (c->r->ascii_font != font || c->r->ascii_fs != c->fs) {
            c->r->ascii_font = font;
            c->r->ascii_fs = c->fs;
            for (int i = 0; i < 128; ++i) {
                int m0 = 0, m1 = 0, m2 = 0, m3 = 0, adv = 0;
                TTF_GetGlyphMetrics(font, static_cast<Uint32>(i),
                                    &m0, &m1, &m2, &m3, &adv);
                c->r->ascii_w[i] = adv;
            }
        }
        return c->r->ascii_w[cp];
    }
    /* non-ASCII: cached per (font, size, codepoint); fallback chain included */
    /* The chain is NOT used for metrics: TTF_GetGlyphMetrics reports the
     * PRIMARY font's .notdef advance for missing glyphs (it does not walk
     * the fallback chain, while TTF_GetGlyphImage does) - measuring the
     * primary font gave CJK a 12px .notdef width at 18px while the paint
     * path drew 18px glyphs. Layout/widths/raster buffers were all off and
     * the last CJK char fell outside the buffer ("婵犵數鍎戠徊钘夌暦椤掑倵鍋撻悷鏉挎毐閺佸牓鏌涚仦鍓х煀闁? lost its 缂?.
     * Measure the FALLBACK font that will actually render the glyph. */
    TTF_Font* gfont = font;
    if (cp >= 0x80 || !TTF_FontHasGlyph(font, cp)) {
        TTF_Font* fb = ensure_fallback(c->r, font, c->fs,
                                       c->bold ? kFontBold : 0, cp);
        if (fb) {
            gfont = fb;
        }
    }
    if (gfont) {
        ensure_font_state(c->r, gfont, c->fs,
                          c->bold ? kFontBold : 0);
    }
    std::tuple<TTF_Font*, int, unsigned int> key(
        gfont, static_cast<int>(c->fs), cp);
    auto it = c->r->glyph_w_cache.find(key);
    if (it != c->r->glyph_w_cache.end()) {
        return it->second;
    }
    int m0 = 0, m1 = 0, m2 = 0, m3 = 0, adv = 0;
    TTF_GetGlyphMetrics(gfont, cp, &m0, &m1, &m2, &m3, &adv);
    c->r->glyph_w_cache[key] = adv;
    return adv;
}

