/* --- stb_truetype 闂備礁鎲￠懝鎯归悜绛嬫晜?婵犵數鍋炲娆擃敄閸涙惌鏁?+ 闁荤喐绮嶆竟瀣疾閻愬鐝跺┑鐘插閸嬫挸鈽夊▎妯荤暥闂?COLR/CPAL,闂備礁鎲￠悷銉╁磹娴犲鐒?stb#512/#1135) --- */

/* 濠电姰鍨归悥銏ゅ椽娴ｉ纾介梺鑽ゅТ濞测晠顢氳閵?sfnt 闂佽崵鍋炵粙蹇涘礉瀹€鍕仱鐟滃秹鍩㈤幘缁橆棃婵炴垶鐟х粔鍨箾?big-endian) */
static unsigned int be16(const unsigned char* p)
{
    return (static_cast<unsigned int>(p[0]) << 8) | p[1];
}
static unsigned int be32(const unsigned char* p)
{
    return (static_cast<unsigned int>(p[0]) << 24) |
           (static_cast<unsigned int>(p[1]) << 16) |
           (static_cast<unsigned int>(p[2]) << 8) | p[3];
}

/* 闂備線娼荤拹鐔煎礉瀹€鍕仱鐟滃酣骞忛崨鏉戠閻庢稒蓱椤斿秹姊虹涵鍜佸殐闁哥姵娲熼幊娆撳箣閿曗偓閽冪喖鏌曟径娑氱暠妞?sfnt 闂?tag 4 闂佽瀛╃粙鎺椼€冩径瀣╃箚?闂備焦鐪归崝宀€鈧凹鍓氱粋宥夊传閵壯呯厠?闂佸搫顦弲婊堝蓟閵娿儍娲冀椤撶喎鍓紓浣割儐椤戞瑩宕甸悩缁樼厸濞达絽鎼。鑲┾偓瑙勬尫閼冲爼骞愯椤︾増鎯旈垾鎻掑闂備焦鐪归崝宀€鈧凹鍓氱粋宥夊传閵壯呯厠?
 * TTC 闂備礁鎲￠悷锕傛偋濠婂牜鏁勯柛銉ｅ妿閳绘棃鏌嶈閸撴氨绮欐径鎰垫晜闁告洦鍘介幉缁樼箾鏉堝墽绋婚柟绋跨埣閸┾偓妞ゆ巻鍋撻柛濠咁潐缁旂喎螣閼姐倐鏋栭悗骞垮劚閹冲酣鎮￠崒鐐茬骇闁冲搫鍊归悡銉︾箾?-1闂?*/
static int font_table_off(const unsigned char* data, size_t len, const char* tag)
{
    if (!data || len < 12) {
        return -1;
    }
    int fontstart = stbtt_GetFontOffsetForIndex(data, 0);
    if (fontstart < 0 || fontstart + 12 > static_cast<int>(len)) {
        return -1;
    }
    unsigned int n = be16(data + fontstart + 4);
    for (unsigned int i = 0; i < n; ++i) {
        size_t r = static_cast<size_t>(fontstart) + 12 + i * 16;
        if (r + 16 > len) {
            return -1;
        }
        const unsigned char* rec = data + r;
        if (rec[0] == static_cast<unsigned char>(tag[0]) &&
            rec[1] == static_cast<unsigned char>(tag[1]) &&
            rec[2] == static_cast<unsigned char>(tag[2]) &&
            rec[3] == static_cast<unsigned char>(tag[3])) {
            unsigned int off = be32(rec + 8);
            return off < len ? static_cast<int>(off) : -1;
        }
    }
    return -1;
}

/* COLR 闂佽绻掗崑娑㈠磹娴犲鏁婇柛銉簵娴?闂佽绻掗崑娑㈠磹閹间焦鍋ょ憸鎴﹀Φ?id + 闂佽崵濮撮鍛村疮閾忣偆鐝跺┑鐘叉搐缁狙囨煙缁嬪灝顒㈤柦鍌氼儔閺?闂備礁鎲￠悷銉╁磹娴犲鐒?stb#1135 闂?stbtt_glyphlayer) */
struct ColrLayer { unsigned short glyph; unsigned short color; };

/* 闂備礁鎼悮顐﹀磿閸欏鐝?glyph 闂?COLR 闂?缂傚倷鑳堕崑鎾垛偓绗涘洤鐒垫い鎴墮鐎氼剟藟閸ヮ剚鐓?base glyph records 闂?glyph id 闂備礁鎲￠〃鍛洪妶鍥С?
 * 闂備浇妗ㄥ鎺楀础閹惰棄闂柧蹇撴贡濡垳鎲稿澶婂惞闁硅揪闄勯崕宀€绱掗懜鐢垫噰鐎规洘鐟╅幃鈺呭箵閹烘棑绱?婵犳鍣徊鐣屾崲閹扮増鍋ょ憸鎴﹀Φ閹板府缍栨い鎾跺娴煎洤鈹戦悙鍙夘棏闁逞屽墮閸熻法鎷嬮弻銉︾厵闁诡厽甯掗崝姘辨喐?闂備線娼уΛ妤呭磹閻ｅ本宕查柟杈剧畱閻愬﹪鏌ｉ幇顖氱毢婵犫偓閹绢喗鐓?0 = 闂佽崵濮村ú銏ゅ磿闁秵鍋ょ憸鎴﹀Φ閹版澘顫呴柍鈺佸枦妤犲繘鏌ｈ箛鏇炰粶闁稿﹤鐖奸崺鈧?*/
static int colr_layers(const unsigned char* data, int colr_off,
                       unsigned int gid, const ColrLayer*& out)
{
    const unsigned char* t = data + colr_off;
    unsigned int n = be16(t + 2);
    unsigned int bgo = be32(t + 4);
    unsigned int lo = be32(t + 8);
    for (unsigned int i = 0; i < n; ++i) {
        const unsigned char* r = t + bgo + i * 6;
        if (be16(r) == gid) {
            unsigned int fi = be16(r + 2);
            unsigned int nl = be16(r + 4);
            out = reinterpret_cast<const ColrLayer*>(t + lo + fi * 4);
            return static_cast<int>(nl);
        }
    }
    return 0;
}

/* CPAL v0 闂佽崵濮撮鍛村疮閾忣偆鐝跺┑鐘叉搐缁狙囨煕瑜庨〃蹇涘级瑜版帗鐓?BGRA 闂備礁鎲￠崝鏇㈠箠鎼淬劍鍋ら柕濠忛檮閸?闂?0xAARRGGBB);colorid==0xFFFF 闂備焦鐪归崹鑲╁垝妤ｅ啯鍎嶉柣鏂垮悑閸?
 * 闂備礁鎼崐绋匡耿闁秴鏋侀柕鍫濐槸缁€鍫⑩偓骞垮劚濡瑩鎮甸鐐寸厾闁荤喐澹嗗﹢鎾煃瑜滈崜娆撳磹濮濆被浜归柛銉㈡櫆鐎氼剟鏌涢幇闈涘箹妞ゃ儱绻橀弻?0(濠碘槅鍋撶徊楣冩偋閺冨牊鐓?闂?*/
static unsigned int colr_palette_color(const unsigned char* data, int cpal_off,
                                       unsigned int colorid)
{
    if (cpal_off < 0 || colorid == 0xFFFF) {
        return 0xFFFFFFFF;
    }
    const unsigned char* t = data + cpal_off;
    unsigned int npa = be16(t + 4);
    unsigned int npe = be16(t + 2);
    if (npa == 0 || colorid >= npe) {
        return 0xFFFFFFFF;
    }
    unsigned int cro = be32(t + 8);
    unsigned int pidx = be16(t + 12); /* palette 0 闂?colorRecordIndices */
    const unsigned char* c = t + cro + pidx * 4 + colorid * 4;
    return (static_cast<unsigned int>(c[3]) << 24) |
           (static_cast<unsigned int>(c[2]) << 16) |
           (static_cast<unsigned int>(c[1]) << 8) | c[0];
}

/* 婵犵數鍋為幐绋款嚕閸洘鍋?COLR 闂備礁鎲＄敮鎺懳涘Δ鍛剳闁规鍠掗崑鎾斥槈濞嗘ɑ鐣堕梺鐓庢憸婢ф绮?RGBA(0xAARRGGBB);闂佸搫顦弲婊堝蓟閵娿儍?false 闂佽崵鍋炵粙蹇涘礉鎼淬劌桅婵娉涚猾宥夋煟濡灝鐨烘繝鈧?闂佽崵濮撮鍛村疮娴兼潙鏋侀柕鍫濐槸濡鐥鐐村殌婵?
 * 闂備礁鎼幏瀣闯閿濆鐒垫い鎺嶇劍閻ㄦ垵霉閻撳孩顥為柟顖涙閺佸啯鎷呴搹鐟版暥闁?闂備線娼уΛ妤呭磹瑜版帗鍎婇柨娑樺濞?stbtt 濠电偠鎻徊鐣岀矓閺夋嚚?+ 闂佽崵濮撮鍛村疮閾忣偆鐝跺┑鐘叉搐缁狙囨煕瑜庨〃蹇涘级瑜版帗鐓?src-over 闂備礁鎲￠懝楣冩偋婵犲洤鍨傛慨妯挎硾杩?*/
static bool colr_render(const stbtt_fontinfo& info, float scale,
                        const unsigned char* data, int colr_off, int cpal_off,
                        unsigned int gid, unsigned int fg,
                        std::vector<unsigned int>& px, int& w, int& h,
                        int& xoff, int& yoff)
{
    const ColrLayer* layers = nullptr;
    int nl = colr_layers(data, colr_off, gid, layers);
    if (nl <= 0) {
        return false;
    }
    struct R { unsigned char* bmp; int w, h, x, y; unsigned int color; };
    std::vector<R> rs;
    int minx = 0x7FFFFFFF, miny = 0x7FFFFFFF, maxx = -0x7FFFFFFF, maxy = -0x7FFFFFFF;
    for (int i = 0; i < nl; ++i) {
        int bw = 0, bh = 0, bx = 0, by = 0;
        unsigned char* bmp = stbtt_GetGlyphBitmap(&info, scale, scale,
                                                  layers[i].glyph,
                                                  &bw, &bh, &bx, &by);
        if (!bmp || bw <= 0 || bh <= 0) {
            stbtt_FreeBitmap(bmp, nullptr);
            continue;
        }
        R r;
        r.bmp = bmp;
        r.w = bw;
        r.h = bh;
        r.x = bx;
        r.y = by;
        r.color = colr_palette_color(data, cpal_off, layers[i].color);
        if (layers[i].color == 0xFFFF) {
            r.color = fg;
        }
        rs.push_back(r);
        if (bx < minx) minx = bx;
        if (by < miny) miny = by;
        if (bx + bw > maxx) maxx = bx + bw;
        if (by + bh > maxy) maxy = by + bh;
    }
    if (rs.empty()) {
        return false;
    }
    w = maxx - minx;
    h = maxy - miny;
    xoff = minx;
    yoff = miny;
    px.assign(static_cast<size_t>(w) * h, 0);
    for (size_t ri = 0; ri < rs.size(); ++ri) {
        const R& r = rs[ri];
        const unsigned int sr = (r.color >> 16) & 0xFF;
        const unsigned int sg = (r.color >> 8) & 0xFF;
        const unsigned int sb = r.color & 0xFF;
        for (int yy = 0; yy < r.h; ++yy) {
            int dy = r.y - miny + yy;
            if (dy < 0 || dy >= h) {
                continue;
            }
            for (int xx = 0; xx < r.w; ++xx) {
                unsigned int sa = r.bmp[yy * r.w + xx];
                if (sa == 0) {
                    continue;
                }
                int dx = r.x - minx + xx;
                if (dx < 0 || dx >= w) {
                    continue;
                }
                unsigned int& d = px[static_cast<size_t>(dy) * w + dx];
                unsigned int da = (d >> 24) & 0xFF;
                /* src-over */
                unsigned int oa = sa + da * (255 - sa) / 255;
                if (oa == 0) {
                    continue;
                }
                unsigned int dr = (d >> 16) & 0xFF;
                unsigned int dg = (d >> 8) & 0xFF;
                unsigned int db = d & 0xFF;
                unsigned int oc = (sr * sa + dr * da * (255 - sa) / 255) / oa;
                unsigned int og = (sg * sa + dg * da * (255 - sa) / 255) / oa;
                unsigned int ob = (sb * sa + db * da * (255 - sa) / 255) / oa;
                d = (oa << 24) | (oc << 16) | (og << 8) | ob;
            }
        }
        stbtt_FreeBitmap(r.bmp, nullptr);
    }
    return true;
}

/* stb font table for measuring (mirrors the draw path in draw_text_at) */
struct StbFonts
{
    struct F { stbtt_fontinfo info; float scale; int asc; int line_h; bool ok; };
    std::vector<F> fonts;
    std::vector<int> colr, cpal; /* 婵犳鍣徊鐣屾崲閹扮増鍋ょ憸搴ㄥ箯?COLR/CPAL 闂佽崵鍋炵粙蹇涘礉鐏炲墽顩查柛婵勫劤閻?闂備礁鎼崯鐗堟叏妤ｅ啫违闁告劏鏅濋埢?-1 */
    size_t pref;
    int line_h;
    explicit StbFonts(const std::string& family, int fs)
        : pref(static_cast<size_t>(-1)), line_h(fs > 0 ? fs : 16)
    {
        whaleui_font_registry* reg = whaleui_font_registry_get();
        if (!reg) {
            return;
        }
        for (size_t fi = 0; fi < reg->count; ++fi) {
            F f;
            f.ok = false;
            f.scale = 1.0f;
            f.asc = 0;
            f.line_h = line_h;
            const unsigned char* d = reg->fonts[fi].data;
            size_t l = reg->fonts[fi].len;
            int co = -1, cp = -1;
            if (d && l >= 4) {
                int off = stbtt_GetFontOffsetForIndex(d, 0);
                if (off >= 0 && stbtt_InitFont(&f.info, d, off)) {
                    f.scale = stbtt_ScaleForPixelHeight(&f.info, static_cast<float>(fs));
                    int desc = 0, linegap = 0;
                    stbtt_GetFontVMetrics(&f.info, &f.asc, &desc, &linegap);
                    f.line_h = static_cast<int>((f.asc - desc + linegap) * f.scale + 0.5f);
                    f.ok = true;
                    line_h = f.line_h;
                    co = font_table_off(d, l, "COLR");
                    cp = font_table_off(d, l, "CPAL");
                }
            }
            colr.push_back(co);
            cpal.push_back(cp);
            fonts.push_back(f);
        }
        /* preferred font: first CSS family match, else first usable font */
        std::vector<std::string> fams = split_families(family);
        for (const std::string& fam : fams) {
            if (fam.empty()) {
                continue;
            }
            bool generic = fam == "sans-serif" || fam == "serif" ||
                           fam == "monospace";
            if (generic) {
                continue;
            }
            for (size_t fi = 0; fi < fonts.size(); ++fi) {
                if (fonts[fi].ok && reg->fonts[fi].family &&
                    std::strcmp(reg->fonts[fi].family, fam.c_str()) == 0) {
                    pref = fi;
                    break;
                }
            }
            if (pref != static_cast<size_t>(-1)) {
                break;
            }
        }
        if (pref == static_cast<size_t>(-1)) {
            for (size_t fi = 0; fi < fonts.size(); ++fi) {
                if (fonts[fi].ok) {
                    pref = fi;
                    break;
                }
            }
        }
    }
    size_t pick(size_t start, unsigned int cp) const
    {
        if (start != static_cast<size_t>(-1) && fonts[start].ok &&
            stbtt_FindGlyphIndex(&fonts[start].info, cp) != 0) {
            return start;
        }
        for (size_t fi = 0; fi < fonts.size(); ++fi) {
            if (fi == start || !fonts[fi].ok) {
                continue;
            }
            if (stbtt_FindGlyphIndex(&fonts[fi].info, cp) != 0) {
                return fi;
            }
        }
        return static_cast<size_t>(-1);
    }
};
/* stb: 闂備礁鎲￠〃鍡椕洪弽顓熷仱鐟滃繒鍒掗銏℃櫇闁逞屽墴瀹曟洖顫濇潏顭戞綗闂佺粯锚濡﹪宕?闂?fallback 闂佽瀛╃粙鎺楀Φ閻愮數绀婇悗锝庡墯閸? */
static int glyph_stb(unsigned int cp, void* st)
{
    StbFonts* f = static_cast<StbFonts*>(st);
    size_t fi = f->pick(f->pref, cp);
    if (fi == static_cast<size_t>(-1)) {
        return 0;
    }
    int adv = 0, lsb = 0;
    stbtt_GetCodepointHMetrics(&f->fonts[fi].info, cp, &adv, &lsb);
    return static_cast<int>(adv * f->fonts[fi].scale + 0.5f);
}

/* stb: 闂佽瀛╃粙鎺椼€冮崨瀛樺殝闁绘鐗婃刊瀵糕偓骞垮劚閹冲繒绮?缂傚倸鍊烽懗鍫曞窗瀹ュ洨鍗?GlyphImg 闂備浇顫夋禍浠嬪磿鏉堫偁浜?闂備線娼уΛ鏃堝疾閻ゎ湌R 闂備礁鎲＄敮鎺懳涘Δ鍛剳闁规鍠掗崑鎾斥槈濞嗘ɑ鐣堕梺鐓庢憸婢ф顭囪箛娑樼闁告劕寮堕惁鏃堟⒑閻撳寒娈犲ù婊勭矒閹粙顢曢敐蹇曠煑濠电姴锕ゅΛ妤吽?
 * (colored=true),闂備礁鎼幏瀣闯閿濆鐒垫い鎺嶆祰婢规﹢鏌ｉ埊娆忔娴滆銇勯顐㈠绩缂佲偓?fg 闂?闂?alpha闂備線娼уΛ妤呭焵椤掆偓閸╊柆f/yoff 濠电偞鍨堕幑浣糕枍閿濆悿瑙勫緞鐏炵浜?pen+baseline
 * 闂備焦鐪归崝宀€鈧凹浜炵槐鐐哄川閺夋垹鍊為梺璇″瀻閸屾粌澧剧紓?stb 闂佽崵濮村ù鍌炲储閾忓湱涓?濠?glyph_stb 闂備礁鎲￠懝楣冨嫉椤掑倽濮虫い鏃€绁归崷顓涘亾閿濆簼鎲鹃柛?闂?*/
static bool glyph_img_stb(StbFonts& stb, unsigned int cp, unsigned int fg,
                          GlyphImg& out)
{
    size_t fi = stb.pick(stb.pref, cp);
    if (fi == static_cast<size_t>(-1)) {
        return false;
    }
    const StbFonts::F& f = stb.fonts[fi];
    int adv = 0, lsb = 0;
    stbtt_GetCodepointHMetrics(&f.info, cp, &adv, &lsb);
    out.advance = static_cast<int>(adv * f.scale + 0.5f);
    unsigned int gid = stbtt_FindGlyphIndex(&f.info, cp);
    if (gid == 0) {
        return false;
    }
    const unsigned char* data = f.info.data;
    if (stb.colr[fi] >= 0 &&
        colr_render(f.info, f.scale, data, stb.colr[fi], stb.cpal[fi],
                    gid, fg, out.px, out.w, out.h, out.xoff, out.yoff)) {
        out.colored = true;
        return true;
    }
    unsigned char* bmp = stbtt_GetGlyphBitmap(&f.info, f.scale, f.scale,
                                              gid, &out.w, &out.h,
                                              &out.xoff, &out.yoff);
    if (!bmp || out.w <= 0 || out.h <= 0) {
        stbtt_FreeBitmap(bmp, nullptr);
        return false;
    }
    out.colored = false;
    out.px.resize(static_cast<size_t>(out.w) * out.h);
    const unsigned int sr = (fg >> 16) & 0xFF;
    const unsigned int sg = (fg >> 8) & 0xFF;
    const unsigned int sb = fg & 0xFF;
    const unsigned int fa = (fg >> 24) & 0xFF; /* 闂備礁鎲￠幐鍝ョ矓闂堟稈鏋?alpha 濠电偞鍨跺褰掓晪闂佺硶鏅涢惉濂稿焵椤掍胶鈯曟い銊ユ嚇閹虫粓鎮ч崼鈶╂灃?*/
    for (size_t i = 0; i < out.px.size(); ++i) {
        unsigned int a = bmp[i] * fa / 255;
        out.px[i] = a ? (a << 24) | (sr << 16) | (sg << 8) | sb : 0;
    }
    stbtt_FreeBitmap(bmp, nullptr);
    return true;
}
#endif

/* 闂佽瀛╃粙鎺椼€冮崨瀛樺殝闁规鍠楅崰鍡涙煕閳╁啫鍤繛鍏兼礋閺岋綁鍩￠崒姘癁闂?ascent + descent/2),闂備焦妞垮鍧楀礉鐎ｎ剝濮虫い鎺戝濡﹢鏌涢妷鎴濇噺閹?闂備胶顭堢换鎰八囨导瀛樺亯?闂傚倷绶￠崑鍕囬婊€鐒婃い鏍仜閸ㄥ倿鏌涚仦鍓х煁缂佺虎鍨堕幃姗€鎮欓崣澶婃闂?
 * 闂佽崵鍋炵粙鎴︽儗閸岀偞鍋?th 闂備礁鎲￠崙褰掑磻婢舵劑鈧線骞嬮悩鍐茬／?闂?th 闂佽绻掗崑娑㈠箠瀹ュ鍤堥柟瀵稿仜椤曡鲸鎱ㄥΟ璇插闁哥偑鍔戦弻锝夊閿濆骸娈┑鐘亾妞ゅ繐妫涚壕浠嬫煙閹冩毐闁哄棗宕—鍐Χ閸涱垰鐓熼梺绋垮閹告娊骞嗛崘顔肩妞ゆ劑鍊栭幉濠氭偡濠婂棗鐒介柛銊ャ偢閿濈偟鈧綆鍓氶崰鍡楊熆鐠虹尨姊楅柣鎺戯工閳藉骞橀幇浣哄姼闂?
 * 濠?draw_text_at 闂備焦鐪归崝宀€鈧凹鍓熼幆鍥惞椤愩倐鏋栧銈嗘尵閸嬬喖宕妸鈺傜厱闁瑰瓨绻冮ˉ娆戠磼閺冣偓閹告娊骞?闂傚倷绶￠崜娆撴倶濠靛鍌?caret 濠电偞鍨堕幐鍝モ偓娑掓櫊瀵悂宕橀浣镐壕婵炴垶鐟▓婊堟煛娴ｉ潻鏀婚柟宄版噹椤撳ジ宕橀敐鍛?*/
int text_glyph_h(whaleui_render_t* r, int fs, const std::string& family,
                 bool bold)
{
    int gh = 0;
#ifdef WHALEUI_BUILD_FULL
    TTF_Font* gfont = render_get_font(r, family, fs, bold ? kFontBold : 0);
    if (gfont) {
        int ga = TTF_GetFontAscent(gfont);
        int gd = TTF_GetFontDescent(gfont);
        if (ga > 0) {
            gh = ga + gd / 2;
        }
    }
#endif
    return gh > 0 ? gh : text_line_h(r, fs, family, bold);
}

void text_size(whaleui_render_t* r, const std::string& text, int fs,
               const std::string& family, bool bold, int* tw, int* th,
               int wrap_w)
{
    *tw = *th = 0;
    if (text.empty() || !r) {
        return;
    }
    /* content-addressed cache: the layout pass measures every run every
     * relayout (a width animation re-lays out each frame) - the layout_text
     * walk below was the per-frame cost. Text/width/face unchanged -> O(1). */
    uint64_t key = 1469598103934665603ull;
    for (size_t i = 0; i < text.size(); ++i) {
        key ^= static_cast<unsigned char>(text[i]);
        key *= 1099511628211ull;
    }
    key ^= static_cast<uint64_t>(fs) * 0x9E3779B97F4A7C15ull;
    key ^= static_cast<uint64_t>(bold) * 0xBF58476D1CE4E5B9ull;
    key ^= static_cast<uint64_t>(wrap_w) * 0x94D049BB133111EBull;
    for (size_t i = 0; i < family.size(); ++i) {
        key ^= static_cast<unsigned char>(family[i]);
        key *= 1099511628211ull;
    }
    auto it = r->text_size_cache.find(key);
    if (it != r->text_size_cache.end()) {
        *tw = it->second.first;
        *th = it->second.second;
        return;
    }
    int lh = text_line_h(r, fs, family, bold);
#ifdef WHALEUI_BUILD_FULL
    TextMeasureCtx mc = { r, fs, family, bold };
    TextLayout L = layout_text(text, wrap_w, lh, glyph_ttf, &mc);
#else
    StbFonts stb(family, fs);
    TextLayout L = layout_text(text, wrap_w, lh, glyph_stb, &stb);
#endif
    *tw = L.tw;
    *th = L.th;
    r->text_size_cache[key] = std::make_pair(*tw, *th);
}

int text_line_h(whaleui_render_t* r, int fs, const std::string& family, bool bold)
{
#ifdef WHALEUI_BUILD_FULL
    TTF_Font* font = render_get_font(r, family, fs,
                                     bold ? kFontBold : 0);
    if (font) {
        int h = TTF_GetFontHeight(font);
        if (h > 0) {
            return h;
        }
    }
    return fs > 0 ? fs : 16;
#else
    StbFonts stb(family, fs > 0 ? fs : 16);
    return stb.line_h;
#endif
}

std::vector<TRect> sel_rects(whaleui_render_t* r, const std::string& text,
                             int fs, const std::string& family, bool bold,
                             size_t a, size_t b, int wrap_w)
{
    std::vector<TRect> out;
    if (a > text.size()) {
        a = text.size();
    }
    if (b > text.size()) {
        b = text.size();
    }
    if (a > b) {
        std::swap(a, b);
    }
    if (a == b || text.empty()) {
        return out;
    }
    int lh = text_line_h(r, fs, family, bold);
#ifdef WHALEUI_BUILD_FULL
    TextMeasureCtx mc = { r, fs, family, bold };
    TextGlyphFn gw = glyph_ttf;
    void* st = &mc;
#else
    StbFonts stb(family, fs);
    TextGlyphFn gw = glyph_stb;
    void* st = &stb;
#endif
    TextLayout L = layout_text(text, wrap_w, lh, gw, st);
    const size_t nc = L.map.size();
    for (size_t li = 0; li < L.lines.size(); ++li) {
        const TextLayoutLine& ln = L.lines[li];
        int xacc = 0;
        int x0 = -1, x1 = -1;
        for (size_t ci = ln.cstart; ci < ln.cend; ++ci) {
            int w = gw(disp_cp_at(L, ci), st);
            if (x0 < 0 && L.map[ci] >= a) {
                x0 = xacc;
            }
            if (x1 < 0 && L.map[ci] >= b) {
                x1 = xacc;
                break;
            }
            xacc += w;
        }
        if (x0 < 0) {
            continue; /* line ends before a */
        }
        if (x1 < 0) {
            x1 = xacc; /* range extends past this line's end */
        }
        if (x1 > x0) {
            TRect rc = {x0, static_cast<int>(li) * lh, x1 - x0, lh};
            out.push_back(rc);
        }
        if (x1 >= xacc) {
            continue; /* keep scanning later lines (range continues) */
        }
        break;
    }
    return out;
}

void caret_pos(whaleui_render_t* r, const std::string& text, int fs,
               const std::string& family, bool bold, size_t off,
               int* cx, int* cy, int* ch, int wrap_w)
{
    int lh = text_line_h(r, fs, family, bold);
    if (lh <= 0) {
        lh = fs > 0 ? fs : 16;
    }
    if (text.empty()) {
        *cx = 0;
        *cy = 0;
        *ch = lh;
        return;
    }
    if (off > text.size()) {
        off = text.size();
    }
#ifdef WHALEUI_BUILD_FULL
    TextMeasureCtx mc = { r, fs, family, bold };
    TextGlyphFn gw = glyph_ttf;
    void* st = &mc;
#else
    StbFonts stb(family, fs);
    TextGlyphFn gw = glyph_stb;
    void* st = &stb;
#endif
    TextLayout L = layout_text(text, wrap_w, lh, gw, st);
    const size_t nc = L.map.size();
    /* 闂?off 闂備礁婀遍。浠嬪磻閹剧粯鐓曢柨鏂挎惈婵偓濡?off 闂備浇袙閸嬫捇鏌﹀Ο渚Ч闂?[闂佽崵鍋炵粙鎴︽儗閸岀偑鈧懏绻濆顒傦紱闂婎偄娲﹀▔? 闂佽崵鍋炵粙鎴︽嚐椤栫偞鍋勬い鎺戝绾惧鐓崶銊﹂暱妞?闂備礁鎲￠悧妤€顪冮挊澹╂盯宕稿Δ鈧繚?
     * 闂佽崵鍋炵粙鎴︽儗閸岀偑鈧懏绻濆顒傜潉?caret 闂備焦鐪归崹濂割敋瑜嶉敃銏ゎ敂閸℃ê鐝伴梺闈涱樈閻撳牓寮?x=0(濠电偞鍨堕幐鍝ョ矓闂堟党锝夊箹娴ｅ摜顦悗骞垮劚鐎氼噣顢旈柆宥嗗仩婵炴垶顭囬悘杈ㄧ箾閸喎鐏╅柟顔藉娴狅箓鎮剧仦鑺ユ)闂?*/
    for (size_t li = 0; li < L.lines.size(); ++li) {
        const TextLayoutLine& ln = L.lines[li];
        size_t ls_off = (ln.cstart < nc) ? L.map[ln.cstart] : off;
        size_t le_off = (ln.cend < nc) ? L.map[ln.cend] : text.size();
        if (off < ls_off) {
            /* 闂備浇袙閸嬫捇鏌﹀Ο渚Ч闂婎剦鍓欓埥澶愬箻缁涜顣肩紓浣规煥椤曨參骞冮幍顔绘勃闁绘劦鍓氶惈姗€鏌ｈ箛鎾剁鐟滄壆鍋熺划濠氭晲婢跺﹨袝闁圭厧鐡ㄧ粙鍫ュ磻閹惧瓨濯撮悷娆忓鐎氭娊鏌ｉ悙瀵糕槈闁活厺绶氶妴渚€骞嬮悜鍥╃＞闂佸搫绋勬俊鍥敇濞差亝鐓?闂備礁鎲￠悷顖涚濠婂喛鑰挎い蹇撴閻艾螖閿旂瓔鍎ラ柡鈧挊澶嗘闁哄倹顑欓崕鏃€淇婇銏″仴闁?
             * \n 濠电姰鍨煎▔娑氣偓姘煎墲閵囨劙寮婚妷锕€娈?闁荤喐绮庢晶妤呭箰妞嬪海绀婇柡鍐ㄧ墕鐎氬銇勯幒鎴濇灓闁衡偓娴犲鍋犳繛鎴烆焽閻掑憡銇勯埡鍐笡鐎垫澘瀚板畷鐔碱敇閻斿皝鍋?*/
            *cx = 0;
            *cy = static_cast<int>(li) * lh;
            *ch = lh;
            return;
        }
        if (off >= ls_off && off <= le_off) {
            int xacc = 0;
            for (size_t ci = ln.cstart; ci < ln.cend; ++ci) {
                if (L.map[ci] >= off) {
                    break;
                }
                xacc += gw(disp_cp_at(L, ci), st);
            }
            *cx = xacc;
            *cy = static_cast<int>(li) * lh;
            *ch = lh;
            return;
        }
    }
    /* 闂備胶顭堢换鎴犲垝瀹€鈧懞?闂備礁鎼崐绋棵洪敃鈧敃銏″閺夋垵鐝樺銈嗗姂閸ㄥ宕?*/
    const TextLayoutLine& last = L.lines.back();
    *cx = last.w;
    *cy = static_cast<int>(L.lines.size() - 1) * lh;
    *ch = lh;
}

